"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[890],{1863:e=>{e.exports=JSON.parse('{"functions":[{"name":"component","desc":"Preregisters a component, without a [World].\\r","params":[],"returns":[{"desc":"","lua_type":"Component<T>"}],"function_type":"static","source":{"line":621,"path":"src/jecs.luau"}},{"name":"tag","desc":"Preregisters a tag component, without a [World].\\r","params":[],"returns":[{"desc":"","lua_type":"Component"}],"function_type":"static","source":{"line":635,"path":"src/jecs.luau"}},{"name":"meta","desc":"Sets metadata onto a Component, without a [World].\\n```lua\\nlocal Name = Jecs.Name\\nlocal Position = Jecs.component()\\nJecs.meta(Position, Name, \\"Position\\")\\n```\\r","params":[],"returns":[],"function_type":"static","source":{"line":651,"path":"src/jecs.luau"}},{"name":"IS_PAIR","desc":"Given an Id, returns whether or not the Id is a pair.","params":[{"name":"id","desc":"The id to check","lua_type":"Id"}],"returns":[{"desc":"Whether it is or is not a pair","lua_type":"boolean"}],"function_type":"static","source":{"line":679,"path":"src/jecs.luau"}},{"name":"pair","desc":"Encodes two Ids into one, to represent a Relationship.\\n```lua\\nlocal Likes = world:component()\\nlocal alice = world:entity()\\nlocal bob = world:entity()\\nworld:add(bob, Jecs.pair(Likes, alice))\\n```\\nFor more information on pairs, read [here](https://github.com/Ukendio/jecs/blob/main/how_to/013_pairs.luau).\\r","params":[],"returns":[{"desc":"","lua_type":"Id"}],"function_type":"static","source":{"line":731,"path":"src/jecs.luau"}},{"name":"world","desc":"Creates a new [World].\\n:::info Debug Mode\\nDebug Mode is available for you to enable when debugging. By\\nenabling it, you are enabling better lints and errors to help\\nyou identify and debug issues.\\nIt is suggested that you test with and without Debug Mode on,\\nthis ensures your production build is also stable.\\n```lua\\nlocal world = Jecs.world(true)\\n```\\n:::\\r","params":[{"name":"DEBUG","desc":"Whether to enable debug mode or not","lua_type":"boolean?"}],"returns":[{"desc":"","lua_type":"World"}],"function_type":"static","source":{"line":3135,"path":"src/jecs.luau"}},{"name":"is_tag","desc":"Given a World and an Id, returns whether or not the given\\nId is a tag.","params":[{"name":"world","desc":"","lua_type":"World"},{"name":"id","desc":"The id to check","lua_type":"Id"}],"returns":[{"desc":"Whether it is or is not a tag","lua_type":"boolean"}],"function_type":"static","source":{"line":4657,"path":"src/jecs.luau"}},{"name":"new","desc":"Given a World, creates a new Entity.","params":[{"name":"world","desc":"","lua_type":"World"}],"returns":[{"desc":"","lua_type":"Entity"}],"function_type":"static","source":{"line":4736,"path":"src/jecs.luau"}},{"name":"new_low_id","desc":"Given a World, creates a new Id at the low range.","params":[{"name":"world","desc":"","lua_type":"World"}],"returns":[{"desc":"","lua_type":"Id"}],"function_type":"static","source":{"line":4750,"path":"src/jecs.luau"}},{"name":"new_w_id","desc":"Given a World, creates a new Id with the given trait.\\n\\n:::note\\nThis is effectively syntax sugar for,\\n\\n```lua\\nlocal entity = world:entity()\\nworld:add(entity, id --[[ Your trait ]])\\n```\\n:::","params":[{"name":"world","desc":"","lua_type":"World"},{"name":"id","desc":"The trait to add","lua_type":"Id"}],"returns":[{"desc":"","lua_type":"Id"}],"function_type":"static","source":{"line":4790,"path":"src/jecs.luau"}}],"properties":[{"name":"OnAdd","desc":"A Component Trait for setting a hook onto a Component, which will\\nrun when the Component has been added to an Entity.\\n```lua\\nlocal Transform: Id<vector> = world:component()\\nworld:set(Transform, Jecs.OnAdd, function(entity: Entity, id: Id<T>, data: T)\\n\\t-- `Transform` has been added to `entity`\\nend)\\n```\\r","lua_type":"Id","source":{"line":424,"path":"src/jecs.luau"}},{"name":"OnRemove","desc":"A Component Trait for setting a hook onto a Component, which will\\nrun when the Component has been removed from an Entity.\\n```lua\\nlocal Transform: Id<vector> = world:component()\\nworld:set(Transform, Jecs.OnRemove, function(entity: Entity, id: Id<T>)\\n\\t-- `Transform` has been removed from `entity`\\nend)\\n```\\r","lua_type":"Id","source":{"line":439,"path":"src/jecs.luau"}},{"name":"OnChange","desc":"A Component Trait for setting a hook onto a Component, which will\\nrun when the data of a Component has been changed on an Entity.\\n```lua\\nlocal Transform: Id<vector> = world:component()\\nworld:set(Transform, Jecs.OnChange, function(entity: Entity, id: Id<T>, data: T)\\n\\t-- `Transform` on `entity` has been changed to `data`\\nend)\\n```\\r","lua_type":"Id","source":{"line":454,"path":"src/jecs.luau"}},{"name":"w","desc":"An alias for [Jecs.Wildcard].\\r","lua_type":"Id","source":{"line":460,"path":"src/jecs.luau"}},{"name":"Wildcard","desc":"An Id used for Wildcard Queries.\\n```lua\\nlocal Likes = world:component()\\nlocal Name = Jecs.Name\\nlocal Wildcard = Jecs.Wildcard\\nfor id, name in world:query(Name, pair(Likes, Wildcard)) do\\n\\tlocal nth = 0\\n\\tlocal likes: Entity? = world:target(entity, Likes, nth)\\n\\twhile likes do\\n\\t\\tlocal friendsName: string? = world:get(likes, Name)\\n\\t\\tprint(`{name} likes {friendsName}`)\\n\\t\\tnth += 1\\n\\t\\tlikes = world:target(entity, Likes, nth)\\n\\tend\\nend\\n```\\r","lua_type":"Id","source":{"line":484,"path":"src/jecs.luau"}},{"name":"ChildOf","desc":"An Id used for Parent-Child hierarchies using Relationships.\\n```lua\\nlocal ChildOf = Jecs.ChildOf\\nlocal Character = world:component()\\nlocal Player = world:component()\\nfor entity in world:query(Character) do\\n\\tlocal player: Entity? = world:parent(entity)\\n\\tprint(world:has(player, Player)) -- Output: true\\nend\\n```\\r","lua_type":"Id","source":{"line":501,"path":"src/jecs.luau"}},{"name":"OnDelete","desc":"A Cleanup Condition which executes when the Entity is deleted.\\nThis is meant to be used with [Jecs.Remove] and [Jecs.Delete] to\\nimplement Cleanup Traits.\\r","lua_type":"Id","source":{"line":511,"path":"src/jecs.luau"}},{"name":"OnDeleteTarget","desc":"A Cleanup Condition for Relationships which executes when the\\ntarget of the relationship is deleted, where the target is the second\\nelement of a pair.\\nThis is meant to be used with [Jecs.Remove] and [Jecs.Delete] to\\nimplement Cleanup Traits.\\r","lua_type":"Id","source":{"line":522,"path":"src/jecs.luau"}},{"name":"Delete","desc":"When used as apart of a Cleanup Trait, it will delete all entities\\nwith the relevant id.\\n```lua\\nlocal OnDelete = Jecs.OnDelete\\nlocal Delete = Jecs.Delete\\nlocal Component = world:component()\\nworld:add(Component, Jecs.pair(OnDelete, Delete))\\nlocal entity = world:entity()\\nworld:add(entity, Component)\\nworld:delete(Component) -- `entity` will be deleted.\\n```\\r","lua_type":"Id","source":{"line":542,"path":"src/jecs.luau"}},{"name":"Remove","desc":"When used as apart of a Cleanup Trait, it will delete all entities\\nwith the relevant id.\\n```lua\\nlocal OnDelete = Jecs.OnDelete\\nlocal Remove = Jecs.Remove\\nlocal Component = world:component()\\nworld:add(Component, Jecs.pair(OnDelete, Remove))\\nlocal entity = world:entity()\\nworld:add(entity, Component)\\nworld:delete(Component) -- `Component` will be removed from `enttiy`\\n```\\r","lua_type":"Id","source":{"line":562,"path":"src/jecs.luau"}},{"name":"Name","desc":"An Id used for setting names on entities.\\n```lua\\nlocal Name = Jecs.Name\\nlocal alice = world:entity()\\nworld:set(alice, Name, \\"Alice\\")\\n```\\r","lua_type":"Id","source":{"line":575,"path":"src/jecs.luau"}},{"name":"Exclusive","desc":"A Component Trait for marking relationships as exclusive, meaning\\nthat the entity can only ever have one target for the relation marked\\nas exclusive, where the target is the second element of a pair.\\r","lua_type":"Id","source":{"line":585,"path":"src/jecs.luau"}},{"name":"Rest","desc":"Entity Ids begin after [Jecs.Rest], other than that, this reserved Id\\nserves essentially no purpose. In the [Jecs Examples](https://github.com/Ukendio/jecs/blob/main/examples/queries/changetracking.luau), it is used\\nas a component for use in change tracking.\\r","lua_type":"Id","source":{"line":593,"path":"src/jecs.luau"}}],"types":[{"name":"Entity","desc":"An alias for [Jecs.Id].\\r","lua_type":"number","source":{"line":95,"path":"src/jecs.luau"}},{"name":"Id","desc":"An Id represents an Entity, a Component, or a Pair. In Jecs, it is\\ntyped as `{ __T: T }` to preserve types on Entities/Components, though\\nit is essentially just a number.\\r","lua_type":"number","source":{"line":103,"path":"src/jecs.luau"}},{"name":"Pair","desc":"Represents a relationship, where the first element is the relation,\\nand the second element is the target.\\nYou can create pairs with [Jecs.pair].\\r","lua_type":"number","source":{"line":112,"path":"src/jecs.luau"}},{"name":"Component","desc":"An alias for [Jecs.Id].\\r","lua_type":"number","source":{"line":118,"path":"src/jecs.luau"}}],"name":"Jecs","desc":"Just a stupidly fast Entity Component System.\\\\\\n\\\\\\nThe Repository for Jecs can be found [here](https://github.com/Ukendio/jecs).\\r","source":{"line":4801,"path":"src/jecs.luau"}}')}}]);